import {spawnSync} from 'node:child_process';import {readFileSync,statSync} from 'node:fs';import assert from 'node:assert/strict';import {sourceSecretScan} from './scripts/ci/security.mjs';import {privateRedactionValues} from './scripts/evidence-lib.mjs';import {sourceFingerprint} from './scripts/documentation-lib.mjs';
